"""Pipeline spec: YAML with stages, per-stage env vars, artifacts, depends_on."""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Any

import yaml


class PipelineError(Exception):
    """Raised for invalid pipeline specifications."""


@dataclass
class Stage:
    name: str
    cmd: str
    env: dict[str, str] = field(default_factory=dict)
    depends_on: list[str] = field(default_factory=list)
    inputs: list[str] = field(default_factory=list)      # paths/globs hashed for cache key
    artifacts: list[str] = field(default_factory=list)   # globs copied into artifact store


@dataclass
class Pipeline:
    root: str                                            # working dir for stages (absolute)
    stages: dict[str, Stage]                             # insertion order from the YAML

    def topo_order(self) -> list[Stage]:
        """Stages in dependency order (Kahn's algorithm). Raises on cycles."""
        indegree = {name: 0 for name in self.stages}
        dependents: dict[str, list[str]] = {name: [] for name in self.stages}
        for stage in self.stages.values():
            for dep in stage.depends_on:
                indegree[stage.name] += 1
                dependents[dep].append(stage.name)

        ready = [name for name, deg in indegree.items() if deg == 0]
        ordered: list[Stage] = []
        while ready:
            # keep a deterministic, stable order
            ready.sort(key=lambda n: list(self.stages).index(n))
            name = ready.pop(0)
            ordered.append(self.stages[name])
            for nxt in dependents[name]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    ready.append(nxt)

        if len(ordered) != len(self.stages):
            unresolved = sorted(set(self.stages) - {s.name for s in ordered})
            raise PipelineError(f"dependency cycle involving: {', '.join(unresolved)}")
        return ordered


def _as_list(value: Any, what: str) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, list) and all(isinstance(v, str) for v in value):
        return list(value)
    raise PipelineError(f"{what} must be a string or a list of strings")


def load_pipeline(path: str) -> Pipeline:
    """Load and validate a pipeline YAML file."""
    path = os.path.abspath(path)
    if not os.path.isfile(path):
        raise PipelineError(f"pipeline file not found: {path}")

    with open(path, encoding="utf-8") as fh:
        data = yaml.safe_load(fh)

    if not isinstance(data, dict):
        raise PipelineError("pipeline must be a mapping at the top level")
    raw_stages = data.get("stages")
    if not isinstance(raw_stages, dict) or not raw_stages:
        raise PipelineError("pipeline must declare a non-empty 'stages' mapping")

    root = os.path.dirname(path)
    stages: dict[str, Stage] = {}
    for name, body in raw_stages.items():
        if not isinstance(body, dict):
            raise PipelineError(f"stage '{name}' must be a mapping")
        cmd = body.get("cmd") or body.get("command")
        if not cmd or not isinstance(cmd, str):
            raise PipelineError(f"stage '{name}' must declare a 'cmd' string")
        env_raw = body.get("env") or {}
        if not isinstance(env_raw, dict):
            raise PipelineError(f"stage '{name}': env must be a mapping")
        stages[name] = Stage(
            name=name,
            cmd=cmd,
            env={str(k): str(v) for k, v in env_raw.items()},
            depends_on=_as_list(body.get("depends_on"), f"stage '{name}' depends_on"),
            inputs=_as_list(body.get("inputs"), f"stage '{name}' inputs"),
            artifacts=_as_list(body.get("artifacts"), f"stage '{name}' artifacts"),
        )

    # validate dependencies exist
    for stage in stages.values():
        for dep in stage.depends_on:
            if dep not in stages:
                raise PipelineError(
                    f"stage '{stage.name}' depends on unknown stage '{dep}'"
                )

    return Pipeline(root=root, stages=stages)

