"""Content-addressed cache keyed on declared stage inputs.

A cache key is a sha256 over:
  - the stage command,
  - the stage env vars,
  - the resolved dependency cache keys (so changes propagate downstream),
  - the sorted list of declared input paths and their file contents.

Keys are stored as JSON marker files under .tinyci/cache/<key>.json; the
artifacts produced by the cached run are stored next to them in a directory.
"""

from __future__ import annotations

import hashlib
import os

# Directories / files that never participate in input hashing.
IGNORED_PARTS = {"__pycache__", ".tinyci", ".git"}
IGNORED_SUFFIXES = {".pyc", ".pyo"}

CACHE_DIR = "cache"


def _iter_input_files(root: str, pattern: str):
    """Yield absolute file paths matching one declared input pattern."""
    path = os.path.join(root, pattern)
    if os.path.isfile(path):
        yield path
        return
    if os.path.isdir(path):
        for dirpath, dirnames, filenames in os.walk(path):
            dirnames[:] = sorted(
                d for d in dirnames
                if d not in IGNORED_PARTS and not d.endswith(".egg-info")
            )
            for fname in sorted(filenames):
                if not fname.endswith(IGNORED_SUFFIXES):
                    yield os.path.join(dirpath, fname)
        return
    if any(ch in pattern for ch in "*?["):
        # glob pattern relative to root
        import glob as _glob

        for hit in sorted(_glob.glob(path, recursive=True)):
            if os.path.isfile(hit) and not hit.endswith(IGNORED_SUFFIXES):
                yield hit


def stage_key(root: str, stage, dep_keys: dict[str, str]) -> str:
    """Compute the content-addressed cache key for a stage.

    ``dep_keys`` maps each of the stage's dependencies to its own key so that
    an upstream change invalidates every dependent stage.
    """
    h = hashlib.sha256()
    h.update(b"cmd\x00" + stage.cmd.encode())
    for k in sorted(stage.env):
        h.update(b"env\x00" + f"{k}={stage.env[k]}".encode())
    for dep in sorted(stage.depends_on):
        h.update(b"dep\x00" + dep.encode() + b"=" + dep_keys.get(dep, "").encode())

    seen: set[str] = set()
    for pattern in sorted(stage.inputs):
        h.update(b"input-pattern\x00" + pattern.encode())
        for fpath in _iter_input_files(root, pattern):
            rel = os.path.relpath(fpath, root)
            if rel in seen:
                continue
            seen.add(rel)
            with open(fpath, "rb") as fh:
                digest = hashlib.sha256(fh.read()).hexdigest()
            h.update(b"file\x00" + rel.encode() + b"\x00" + digest.encode())
    return h.hexdigest()


class Cache:
    """Stores/loads cache entries under <base>/cache."""

    def __init__(self, base: str):
        self.dir = os.path.join(base, CACHE_DIR)

    def _entry(self, key: str) -> str:
        return os.path.join(self.dir, key)

    def has(self, key: str) -> bool:
        return os.path.isfile(self._entry(key))

    def store(self, key: str, artifacts: dict[str, str]) -> None:
        """Persist a cache entry. ``artifacts`` maps run-artifact paths to the
        original relative source paths so they can be restored later."""
        os.makedirs(self._dir_for(key), exist_ok=True)
        import json

        with open(self._entry(key), "w", encoding="utf-8") as fh:
            json.dump({"artifacts": artifacts}, fh)

    def load(self, key: str) -> dict[str, str] | None:
        import json

        entry = self._entry(key)
        if not os.path.isfile(entry):
            return None
        with open(entry, encoding="utf-8") as fh:
            data = json.load(fh)
        return data.get("artifacts", {})

    def artifact_source(self, key: str, rel_path: str) -> str | None:
        src = os.path.join(self._dir_for(key), rel_path)
        return src if os.path.isfile(src) else None

    def _dir_for(self, key: str) -> str:
        return os.path.join(self.dir, key + ".d")

