"""history: read run metadata (JSON under .tinyci/runs/) and list runs."""

from __future__ import annotations

import json
import os
from typing import Iterator

STATUS_MARK = {
    "success": "\u2713",
    "cached": "\u21bb",
    "failed": "\u2717",
    "skipped": "-",
}


def iter_runs(base_dir: str) -> Iterator[dict]:
    """Yield parsed run metadata dicts from <base_dir>/runs/*.json."""
    runs_dir = os.path.join(base_dir, "runs")
    if not os.path.isdir(runs_dir):
        return
    for fname in sorted(os.listdir(runs_dir)):
        if not fname.endswith(".json"):
            continue
        with open(os.path.join(runs_dir, fname), encoding="utf-8") as fh:
            yield json.load(fh)


def list_runs(base_dir: str) -> list[dict]:
    """All runs, oldest first (by trigger time)."""
    runs = list(iter_runs(base_dir))
    runs.sort(key=lambda r: r.get("trigger_time", ""))
    return runs


def format_history(runs: list[dict]) -> str:
    lines = []
    for run in runs:
        lines.append(
            f"run {run['run_id']}  triggered {run.get('trigger_time', '?')}"
        )
        for name, info in run.get("stages", {}).items():
            mark = STATUS_MARK.get(info["status"], "?")
            dur = info.get("duration_s", 0.0)
            note = " (cache)" if info["status"] == "cached" else ""
            lines.append(
                f"  [{mark}] {name:<12} {info['status']:<8} {dur:>8.3f}s{note}"
            )
    return "\n".join(lines)

